function issueKey(issue: ExportIssue, index: number): string {
  return [
    issue.projectItemId ?? '',
    issue.moduleCode ?? '',
    issue.partId ?? issue.partCode ?? '',
    issue.field,
    String(index),
  ].join('|');
}

function formatIssueMeta(issue: ExportIssue): string {
  const parts: string[] = [];
  if (issue.moduleCode) parts.push(`mueble ${issue.moduleCode}`);
  if (issue.partCode) parts.push(`pieza ${issue.partCode}`);
  else if (issue.partId) parts.push(`pieza ${issue.partId}`);
  if (issue.field) parts.push(`campo ${issue.field}`);
  if (issue.optionGroupCode) parts.push(`opción ${issue.optionGroupCode}`);
  return parts.join(' · ');
}

export function ExportIssueList({
  issues,
  title = 'No se puede exportar. Corregí estos problemas:',
}: ExportIssueListProps): ReactNode {
  if (issues.length === 0) return null;

  return (
    <div
      className="export-issues"
      role="alert"
      aria-live="assertive"
      aria-label="Errores de export"
    >
      <p className="export-issues__title">{title}</p>
      <ul className="export-issues__list">
        {issues.map((issue, index) => {
          const meta = formatIssueMeta(issue);
          return (
            <li key={issueKey(issue, index)} className="export-issues__item">
              <span className="export-issues__message">{issue.message}</span>
              {meta ? (
                <span className="export-issues__meta">{meta}</span>
              ) : null}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export function planAmbientScene(opts: {
  readonly lightMode: SceneLightingMode;
  readonly ambientFloor?: AmbientMaterial;
  readonly ambientWall?: AmbientMaterial;
  readonly ambientCeiling?: AmbientMaterial;
  readonly showCeiling?: boolean;
  readonly showFloor?: boolean;
}): AmbientScenePlan {
  const {
    lightMode,
    ambientFloor,
    ambientWall,
    ambientCeiling,
    showCeiling,
    showFloor = true,
  } = opts;
  const isAmbientMode = lightMode !== 'catalog';
  return {
    ambientFloor: isAmbientMode && Boolean(ambientFloor) && showFloor,
    ambientWall: isAmbientMode && Boolean(ambientWall),
    roomBox: isAmbientMode && Boolean(ambientWall),
    ceiling: isAmbientMode && (Boolean(showCeiling) || Boolean(ambientCeiling)),
    contactShadow: isAmbientMode
      ? contactShadowForFloor(ambientFloor?.previewColor)
      : null,
  };
}

function resolveAmbientPhysical(
  material: AmbientMaterial | undefined,
  lightingMode: SceneLightingMode,
): AmbientPhysical {
  const base = boardPhysicalResponse({
    hasMap: Boolean(material?.previewTextureUrl),
    hasGrain: false,
    lightingMode,
  });
  return {
    roughness: material?.previewRoughness ?? base.roughness,
    metalness: material?.previewMetalness ?? base.metalness,
    clearcoat: material?.previewClearcoat ?? base.clearcoat,
    clearcoatRoughness: base.clearcoatRoughness,
    envMapIntensity: base.envMapIntensity,
  };
}

