export function InternalCommsPanel({
  project,
  messages = [],
  assignableOwners = [],
  currentUserId,
  onSendMessage,
  onUpdateTechnicalWorkflow,
}: InternalCommsPanelProps) {
  const [activeFilter, setActiveFilter] = useState<'all' | ProjectInternalMessageType>('all');
  const [messageType, setMessageType] = useState<ProjectInternalMessageType>('comment');
  const [content, setContent] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [actionComment, setActionComment] = useState('');
  const [showCommentInputForStatus, setShowCommentInputForStatus] = useState<ProjectTechnicalStatus | null>(null);

  const currentTechStatus = project.technicalStatus ?? 'pending_assignment';
  const statusMeta = TECHNICAL_STATUS_METADATA[currentTechStatus];
  const availableTransitions = useMemo(
    () => getAvailableTechnicalTransitions(currentTechStatus),
    [currentTechStatus],
  );

  const filteredMessages = useMemo(() => {
    if (activeFilter === 'all') return messages;
    return messages.filter((m) => m.messageType === activeFilter);
  }, [messages, activeFilter]);

  const ownerLabel = useMemo(() => {
    if (!project.ownerUserId) return 'Sin asignar (Ventas)';
    const found = assignableOwners.find((o) => o.id === project.ownerUserId);
    return found ? found.label : project.ownerUserId;
  }, [project.ownerUserId, assignableOwners]);

  const engineerLabel = useMemo(() => {
    if (!project.assignedEngineerId) return 'Sin asignar';
    const found = assignableOwners.find((o) => o.id === project.assignedEngineerId);
    return found ? found.label : project.assignedEngineerId;
  }, [project.assignedEngineerId, assignableOwners]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() || isSending) return;
    try {
      setIsSending(true);
      await onSendMessage({
        messageType,
        content: content.trim(),
      });
      setContent('');
    } finally {
      setIsSending(false);
    }
  };

  const handleTransitionClick = (targetStatus: ProjectTechnicalStatus) => {
    if (targetStatus === 'changes_requested' || targetStatus === 'approved_for_production') {
      setShowCommentInputForStatus(targetStatus);
    } else {
      void onUpdateTechnicalWorkflow({
        technicalStatus: targetStatus,
      });
    }
  };

// Sync target ref with controls target each frame
useFrame(() => {
  if (controlsRef.current?.target) {
    targetRef.current.copy(controlsRef.current.target);
  }
});

useEffect(() => {
  const el = controlsRef.current?.domElement?.parentElement;
  if (!el) return;

  const handleKeyDown = (e: KeyboardEvent) => {
    // Only handle keys when the canvas wrapper has focus
    if (!el.contains(document.activeElement) && document.activeElement !== el) {
      return;
    }

    const controls = controlsRef.current;
    if (!controls) return;

    const target = targetRef.current;
    const offset = new THREE.Vector3().subVectors(camera.position, target);
    const dist = offset.length();

    switch (e.key) {
      case 'ArrowLeft': {
        e.preventDefault();
        const angle = ORBIT_STEP;
        const cos = Math.cos(angle);
        const sin = Math.sin(angle);
        const x = offset.x * cos - offset.z * sin;
        const z = offset.x * sin + offset.z * cos;
        camera.position.set(target.x + x, camera.position.y, target.z + z);
        camera.lookAt(target);
        controls.update();
        onAction?.('Cámara rotada a la izquierda');
        break;
      }
      case 'ArrowRight': {
        e.preventDefault();
        const angle = -ORBIT_STEP;
        const cos = Math.cos(angle);
        const sin = Math.sin(angle);
        const x = offset.x * cos - offset.z * sin;
        const z = offset.x * sin + offset.z * cos;
        camera.position.set(target.x + x, camera.position.y, target.z + z);
        camera.lookAt(target);
        controls.update();
        onAction?.('Cámara rotada a la derecha');
        break;
      }
      case 'ArrowUp': {
        e.preventDefault();
        camera.position.y += dist * ORBIT_STEP;
        camera.lookAt(target);
        controls.update();
        onAction?.('Vista elevada');
        break;
      }
      case 'ArrowDown': {
        e.preventDefault();
        camera.position.y -= dist * ORBIT_STEP;
        camera.lookAt(target);
        controls.update();
        onAction?.('Vista descendida');
        break;
      }
      case '+':
      case '=': {
        e.preventDefault();
        const dir = new THREE.Vector3().subVectors(target, camera.position).normalize();
        camera.position.addScaledVector(dir, dist * ZOOM_STEP);
        controls.update();
        onAction?.('Zoom acercado');
        break;
      }
      case '-':
      case '_': {
        e.preventDefault();
        const dir = new THREE.Vector3().subVectors(target, camera.position).normalize();
        camera.position.addScaledVector(dir, -dist * ZOOM_STEP);
        controls.update();
        onAction?.('Zoom alejado');
        break;
      }
    }
  };

  el.addEventListener('keydown', handleKeyDown);
  return () => el.removeEventListener('keydown', handleKeyDown);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [camera, controlsRef]);

export function KeyboardNav({
  active,
  controlsRef,
  center,
}: KeyboardNavProps): ReactNode {
  const [announcement, setAnnouncement] = useState('');

  const handleKeyAction = useCallback((msg: string) => {
    setAnnouncement('');
    // Force re-render so screen reader picks up new text
    requestAnimationFrame(() => setAnnouncement(msg));
  }, []);

  if (!active) return null;
  return (
    <>
      <KeyboardNavInner controlsRef={controlsRef} center={center} onAction={handleKeyAction} />
      {/* Screen reader announcement region */}
      <Html>
        <div
          className="sr-only"
          role="status"
          aria-live="polite"
          aria-atomic="true"
        >
          {announcement}
        </div>
      </Html>
    </>
  );
}

