function normalize(s: string): string {
  return s
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLocaleLowerCase('es-MX');
}

function matchesQuery(item: CommandPaletteItem, q: string): boolean {
  if (!q) return true;
  const hay = normalize(
    `${item.label} ${item.group} ${item.keywords ?? ''} ${item.id}`,
  );
  return hay.includes(q);
}

const filtered = useMemo(() => {
  const q = normalize(query.trim());
  return items.filter((item) => matchesQuery(item, q));
}, [items, query]);

// Reset when opened
useEffect(() => {
  if (!open) return;
  setQuery('');
  setActiveIndex(0);
  const t = window.setTimeout(() => inputRef.current?.focus(), 0);
  return () => window.clearTimeout(t);
}, [open]);

// Keep active index in range
useEffect(() => {
  if (activeIndex >= filtered.length) {
    setActiveIndex(Math.max(0, filtered.length - 1));
  }
}, [filtered.length, activeIndex]);

// Body scroll lock while open
useEffect(() => {
  if (!open) return;
  const prev = document.body.style.overflow;
  document.body.style.overflow = 'hidden';
  return () => {
    document.body.style.overflow = prev;
  };
}, [open]);

const selectIndex = useCallback(
  (index: number) => {
    const item = filtered[index];
    if (!item) return;
    onSelect(item.id);
    onClose();
  },
  [filtered, onSelect, onClose],
);

const onKeyDown = (event: ReactKeyboardEvent) => {
  if (event.key === 'Escape') {
    event.preventDefault();
    event.stopPropagation();
    onClose();
    return;
  }
  if (event.key === 'ArrowDown') {
    event.preventDefault();
    setActiveIndex((i) =>
      filtered.length === 0 ? 0 : (i + 1) % filtered.length,
    );
    return;
  }
  if (event.key === 'ArrowUp') {
    event.preventDefault();
    setActiveIndex((i) =>
      filtered.length === 0
        ? 0
        : (i - 1 + filtered.length) % filtered.length,
    );
    return;
  }
  if (event.key === 'Enter') {
    event.preventDefault();
    selectIndex(activeIndex);
  }
};

export function useCommandPaletteHotkey(
  onToggle: () => void,
  enabled = true,
): void {
  useEffect(() => {
    if (!enabled) return;
    const onKeyDown = (event: KeyboardEvent) => {
      const isModK =
        (event.metaKey || event.ctrlKey) &&
        (event.key === 'k' || event.key === 'K');
      if (!isModK) return;

      const target = event.target as HTMLElement | null;
      const tag = target?.tagName;
      const isEditable =
        tag === 'INPUT' ||
        tag === 'TEXTAREA' ||
        tag === 'SELECT' ||
        target?.isContentEditable;
      // Still allow Cmd+K from inputs to open palette (Linear-style)
      if (isEditable && (event.key as string) === '/' && !event.metaKey && !event.ctrlKey) {
        return;
      }

      event.preventDefault();
      onToggle();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [onToggle, enabled]);
}

