export function FullscreenDialog({
  open,
  onClose,
  title,
  children,
  showTitle = false,
  escapeEnabled = true,
  dataTestId,
}: FullscreenDialogProps) {
  const titleId = useId();
  const panelRef = useRef<HTMLDivElement>(null);
  const previouslyFocused = useRef<HTMLElement | null>(null);

  // Body scroll lock while open
  useEffect(() => {
    if (!open) return;
    const body = document.body;
    const previous = body.style.overflow;
    body.style.overflow = 'hidden';
    return () => {
      body.style.overflow = previous;
    };
  }, [open]);

  // Focus management: store previous, focus panel, restore on close
  useEffect(() => {
    if (!open) return;
    previouslyFocused.current =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    const focusInitial = () => {
      const panel = panelRef.current;
      if (!panel) return;
      (getFocusable(panel)[0] ?? panel).focus();
    };
    const t = window.setTimeout(focusInitial, 0);
    return () => {
      window.clearTimeout(t);
      previouslyFocused.current?.focus?.();
    };
  }, [open]);

  // Esc closes
  useEffect(() => {
    if (!open || !escapeEnabled) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        onClose();
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [open, escapeEnabled, onClose]);

  const onPanelKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLDivElement>) => {
      if (event.key !== 'Tab') return;
      const panel = panelRef.current;
      if (!panel) return;
      const focusable = getFocusable(panel);
      if (focusable.length === 0) {
        event.preventDefault();
        panel.focus();
        return;
      }
      const first = focusable[0]!;
      const last = focusable[focusable.length - 1]!;
      const active = document.activeElement;
      if (event.shiftKey) {
        if (active === first || active === panel) {
          event.preventDefault();
          last.focus();
        }
      } else if (active === last) {
        event.preventDefault();
        first.focus();
      }
    },
    [],
  );

  if (!open || typeof document === 'undefined') {
    return null;
  }

  return createPortal(
    <div
      ref={panelRef}
      className="fullscreen-dialog"
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      tabIndex={-1}
      onKeyDown={onPanelKeyDown}
      data-testid={dataTestId}
    >
      <h2 id={titleId} className={showTitle ? 'fullscreen-dialog__title' : 'sr-only'}>
        {title}
      </h2>
      {children}
    </div>,
    document.body,
  );
}

export function DropdownMenu({
  ariaLabel,
  triggerLabel,
  triggerIcon,
  disabled = false,
  triggerClassName = 'btn',
  sections,
  onClose,
}: DropdownMenuProps): ReactElement {
  const [open, setOpen] = useState(false);
  const [highlight, setHighlight] = useState(-1);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const menuRef = useRef<HTMLUListElement | null>(null);
  const menuId = useId();

  const flat = flattenItems(sections);
  const enabled = flat.filter((item) => !item.disabled);

  const close = useCallback(() => {
    setOpen(false);
    setHighlight(-1);
    onClose?.();
  }, [onClose]);

  const openMenu = useCallback(() => {
    setOpen(true);
    setHighlight(enabled.length > 0 ? flat.indexOf(enabled[0]!) : -1);
  }, [enabled, flat]);

  const toggle = useCallback(() => {
    if (open) close();
    else openMenu();
  }, [open, openMenu, close]);

  // Close on outside click.
  useEffect(() => {
    if (!open) return;
    const handler = (event: MouseEvent): void => {
      const target = event.target as Node | null;
      if (target && menuRef.current?.contains(target)) return;
      if (target && triggerRef.current?.contains(target)) return;
      close();
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open, close]);

  // Move focus to highlighted item when menu opens or highlight changes.
  useLayoutEffect(() => {
    if (!open || highlight < 0) return;
    const el = menuRef.current?.querySelector<HTMLElement>(
      `[data-index="${highlight}"]`,
    );
    el?.focus();
  }, [open, highlight]);

  const onTriggerKeyDown = (event: React.KeyboardEvent): void => {
    if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      if (!open) openMenu();
    } else if (event.key === 'Escape' && open) {
      event.preventDefault();
      close();
      triggerRef.current?.focus();
    }
  };

  const onMenuKeyDown = (event: React.KeyboardEvent): void => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      const currentIdx = flat.findIndex((item, idx) => idx === highlight);
      for (let i = currentIdx + 1; i < flat.length; i++) {
        if (!flat[i]!.disabled) {
          setHighlight(i);
          return;
        }
      }
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      const currentIdx = flat.findIndex((_, idx) => idx === highlight);
      for (let i = currentIdx - 1; i >= 0; i--) {
        if (!flat[i]!.disabled) {
          setHighlight(i);
          return;
        }
      }
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      const item = flat[highlight];
      if (item && !item.disabled) {
        item.onSelect();
        close();
        triggerRef.current?.focus();
      }
    } else if (event.key === 'Escape') {
      event.preventDefault();
      close();
      triggerRef.current?.focus();
    }
  };

  let runningIndex = -1;

  return (
    <div className="dropdown-menu">
      <button
        ref={triggerRef}
        type="button"
        className={triggerClassName}
        disabled={disabled}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        onClick={toggle}
        onKeyDown={onTriggerKeyDown}
      >
        {triggerIcon}
        <span>{triggerLabel}</span>
        <ChevronsUpDown
          size={14}
          strokeWidth={1.5}
          aria-hidden
          className="dropdown-menu__chevron"
        />
      </button>

      {open ? (
        <ul
          ref={menuRef}
          id={menuId}
          className="dropdown-menu__list"
          role="menu"
          aria-label={ariaLabel}
          onKeyDown={onMenuKeyDown}
        >
          {sections.map((section) => (
            <li key={section.id} className="dropdown-menu__section" role="none">
              {section.label ? (
                <div className="dropdown-menu__section-label" role="presentation">
                  {section.label}
                </div>
              ) : null}
              <ul className="dropdown-menu__section-items" role="none">
                {section.items.map((item) => {
                  runningIndex += 1;
                  const idx = runningIndex;
                  const isHighlighted = idx === highlight;
                  return (
                    <li
                      key={`${section.id}-${item.id}`}
                      data-index={idx}
                      role="menuitem"
                      tabIndex={item.disabled ? -1 : isHighlighted ? 0 : -1}
                      aria-disabled={item.disabled || undefined}
                      className={[
                        'dropdown-menu__item',
                        item.disabled ? 'dropdown-menu__item--disabled' : '',
                        isHighlighted ? 'dropdown-menu__item--highlighted' : '',
                      ]
                        .filter(Boolean)
                        .join(' ')}
                      onMouseEnter={() => !item.disabled && setHighlight(idx)}
                      onClick={() => {
                        if (item.disabled) return;
                        item.onSelect();
                        close();
                        triggerRef.current?.focus();
                      }}
                    >
                      {item.icon ? (
                        <span className="dropdown-menu__item-icon">
                          {item.icon}
                        </span>
                      ) : null}
                      <span className="dropdown-menu__item-text">
                        <span className="dropdown-menu__item-label">
                          {item.label}
                        </span>
                        {item.hint ? (
                          <span className="dropdown-menu__item-hint">
                            {item.hint}
                          </span>
                        ) : null}
                      </span>
                    </li>
                  );
                })}
              </ul>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

export function CatalogTable<T extends { readonly id: string }>({
  columns,
  rows,
  selectedId,
  expandedId,
  isInactive,
  emptyMessage = 'No hay ítems para mostrar.',
  getRowActions,
  onRowClick,
  renderExpandedDetail,
}: CatalogTableProps<T>): ReactNode {
  if (rows.length === 0) {
    return <p className="catalog-empty">{emptyMessage}</p>;
  }

  // Rows only advertise expandability when clicking them reveals the inline
  // detail; without renderExpandedDetail the chevron would promise the wrong
  // thing (design.md §4.2).
  const expandable = Boolean(onRowClick && renderExpandedDetail);
  const colSpan =
    columns.length + (expandable ? 1 : 0) + (getRowActions ? 1 : 0);

  return (
    <div className="catalog-table-wrap">
      <table
        className="catalog-table"
        aria-rowcount={rows.length + 1}
      >
        <thead>
          <tr>
            {expandable ? (
              <th className="catalog-table__expander-head" scope="col">
                <span className="visually-hidden">Detalle</span>
              </th>
            ) : null}
            {columns.map((col) => (
              <th key={col.key} scope="col">
                {col.header}
              </th>
            ))}
            {getRowActions ? (
              <th className="catalog-table__actions-head" scope="col">
                <span className="visually-hidden">Acciones</span>
              </th>
            ) : null}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const inactive = isInactive?.(row) ?? false;
            const selected = selectedId === row.id;
            const expanded = expandedId === row.id;
            const className = [
              'catalog-table__row',
              inactive ? 'is-inactive' : '',
              selected || expanded ? 'is-selected' : '',
              onRowClick ? 'is-clickable' : '',
            ]
              .filter(Boolean)
              .join(' ');

            const handleKeyDown = (event: KeyboardEvent<HTMLTableRowElement>) => {
              if (!onRowClick) return;
              // Ignore keys that originated on nested controls (actions).
              const target = event.target as HTMLElement | null;
              if (
                target &&
                target !== event.currentTarget &&
                target.closest('button, a, input, select, textarea, [role="button"]')
              ) {
                return;
              }
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                onRowClick(row);
              }
            };

            return (
              <Fragment key={row.id}>
                <tr
                  className={className || undefined}
                  onClick={onRowClick ? () => onRowClick(row) : undefined}
                  onKeyDown={onRowClick ? handleKeyDown : undefined}
                  tabIndex={onRowClick ? 0 : undefined}
                  aria-expanded={expandable ? expanded : undefined}
                  data-expanded={expanded ? 'true' : undefined}
                >
                  {expandable ? (
                    <td className="catalog-table__expander-cell">
                      <span
                        className="catalog-table__expander"
                        data-expanded={expanded ? 'true' : undefined}
                      >
                        <ChevronRight
                          size={16}
                          strokeWidth={1.5}
                          aria-hidden="true"
                        />
                      </span>
                    </td>
                  ) : null}
                  {columns.map((col) => (
                    <td key={col.key}>{col.render(row)}</td>
                  ))}
                  {getRowActions ? (
                    <td className="catalog-table__actions-cell">
                      <div
                        className="catalog-table__actions"
                        onClick={(e) => e.stopPropagation()}
                        onKeyDown={(e) => e.stopPropagation()}
                      >
                        {getRowActions(row)}
                      </div>
                    </td>
                  ) : null}
                </tr>
                {expanded && renderExpandedDetail ? (
                  <tr className="catalog-table__detail-row">
                    <td colSpan={colSpan}>
                      <div className="catalog-row-detail">
                        {renderExpandedDetail(row)}
                      </div>
                    </td>
                  </tr>
                ) : null}
              </Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

