export interface HardwareFormModalProps {
  readonly open: boolean;
  readonly editingId: string | null;
  readonly formId: string;
  readonly draft: HardwareDraft;
  readonly setDraft: Dispatch<SetStateAction<HardwareDraft>>;
  readonly error: string | null;
  readonly canMutate: boolean;
  readonly onUploadImage?: (file: File) => Promise<string>;
  readonly resolveImageUrl: (url: string | undefined) => string | undefined;
  readonly onSubmit: (e: FormEvent) => void;
  readonly onClose: () => void;
}

export function HardwareFormModal({
  open,
  editingId,
  formId,
  draft,
  setDraft,
  error,
  canMutate,
  onUploadImage,
  resolveImageUrl,
  onSubmit,
  onClose,
}: HardwareFormModalProps): ReactNode {
  const [preview3dOpen, setPreview3dOpen] = useState(false);

  // Reset the disclosure each time the modal opens: editing an item with a
  // configured shape opens it, creating starts collapsed (F117 fix).
  const [wasOpen, setWasOpen] = useState(false);
  if (open && !wasOpen) {
    setWasOpen(true);
    setPreview3dOpen(Boolean(draft.previewShape));
  } else if (!open && wasOpen) {
    setWasOpen(false);
  }

  const selectedFinishId = matchHardwareFinish({
    color: draft.previewColor,
    metalness: draft.previewMetalness,
    roughness: draft.previewRoughness,
    clearcoat: draft.previewClearcoat,
  });

  /** F080: part-finish selectors appear for multi-part shapes only. */
  const partRoles = (() => {
    const validShapes: readonly string[] = [
      'knob',
      'bar-pull',
      'cup-pull',
      'hinge',
      'slide',
      'rail',
      'leg',
    ];
    if (!validShapes.includes(draft.previewShape)) return [];
    const roles = hardwarePartRolesForShape(
      draft.previewShape as NonNullable<Hardware['previewShape']>,
    );
    return roles.length >= 2 ? roles : [];
  })();

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={editingId ? 'Editar herraje' : 'Nuevo herraje'}
      size="sm"
      dataTestId="hardware-form-modal"
      footer={
        <>
          <button type="button" className="btn" onClick={onClose}>
            Cancelar
          </button>
          <button type="submit" className="btn btn--primary" form={formId}>
            Guardar
          </button>
        </>
      }
    >
      <form id={formId} className="catalog-form" onSubmit={onSubmit}>
        {error ? <p className="catalog-form__error">{error}</p> : null}

        <fieldset
          className="catalog-form__section"
          data-testid="hardware-form-identity"
        >
          <legend className="catalog-form__section-title">Identidad</legend>
          <div className="catalog-form__field">
            <label htmlFor="hw-code">Código</label>
            <input
              id="hw-code"
              value={draft.code}
              onChange={(e) => setDraft({ ...draft, code: e.target.value })}
              autoComplete="off"
              required
            />

export function StockMovementModal({
  type,
  initialKind,
  initialMaterialId,
  catalogOptions,
  labels,
  onClose,
  onSubmit,
}: StockMovementModalProps): ReactNode {
  const [kind, setKind] = useState<StockMaterialKind>(initialKind ?? 'herrajes');
  const [materialId, setMaterialId] = useState(initialMaterialId ?? '');
  const [quantity, setQuantity] = useState('');
  const [note, setNote] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const optionsForKind = useMemo(
    () => catalogOptions.find((o) => o.kind === kind)?.items ?? [],
    [catalogOptions, kind],
  );

  const submit = async (): Promise<void> => {
    const qty = Number(quantity);
    if (!materialId) {
      setError('Elegí un material');
      return;
    }
    if (!Number.isFinite(qty) || (type !== 'ajuste' && qty <= 0) || (type === 'ajuste' && qty === 0)) {
      setError(
        type === 'ajuste'
          ? 'El ajuste no puede ser cero'
          : 'Ingresá una cantidad mayor a cero',
      );
      return;
    }
    if (type === 'ajuste' && note.trim() === '') {
      setError('El ajuste requiere una nota (conteo físico, motivo)');
      return;
    }
    setSaving(true);
    setError(null);
    try {
      await onSubmit({
        kind,
        materialId,
        type,
        quantity: qty,
        note: note.trim() ? note.trim() : undefined,
      });
      onClose();
    } catch (err) {
      setError(
        err instanceof Error ? err.message : 'No se pudo registrar el movimiento',
      );
      setSaving(false);
    }
  };

  const Icon =
    type === 'entrada' ? PackagePlus : type === 'salida' ? PackageMinus : SlidersHorizontal;

  return (
    <Modal
      open
      onClose={onClose}
      title={TITLES[type]}
      size="sm"
      dataTestId="purch-stock-modal"
      footer={
        <div className="purch-stock-modal__footer">
          {error ? (
            <span className="purch-stock-modal__error" data-testid="purch-stock-modal-error">
              {error}
            </span>
          ) : null}
          <div className="purch-stock-modal__actions">
            <button type="button" className="btn btn--secondary btn--small" onClick={onClose}>
              Cancelar
            </button>
            <button
              type="button"
              className="btn btn--primary btn--small"
              onClick={() => void submit()}
              disabled={saving}
              data-testid="purch-stock-modal-submit"
            >
              <Icon size={14} strokeWidth={1.5} aria-hidden />
              {saving ? 'Guardando…' : STOCK_MOVEMENT_LABELS_ES[type]}
            </button>
          </div>
        </div>
      }

export function StudioDeleteDialog({
  open,
  targets,
  hasPlacedSelection,
  canRemoveFromProject,
  onCancel,
  onConfirm,
}: StudioDeleteDialogProps): ReactNode {
  const defaultScope: StudioDeleteScope = hasPlacedSelection ? 'plan' : 'project';
  const [scope, setScope] = useState<StudioDeleteScope>(defaultScope);

  // Al (re)abrir el diálogo vuelve al alcance default del contexto actual.
  useEffect(() => {
    if (open) setScope(defaultScope);
  }, [open, defaultScope]);

  if (targets.length === 0) return null;

  const label =
    targets.length === 1
      ? targets[0]!.code === '—'
        ? targets[0]!.name
        : `${targets[0]!.code} · ${targets[0]!.name}`
      : `${targets.length} muebles`;

  return (
    <Modal
      open={open}
      onClose={onCancel}
      title={targets.length === 1 ? 'Eliminar mueble' : 'Eliminar muebles'}
      size="sm"
      dataTestId="studio-delete-dialog"
      footer={
        <>
          <button
            type="button"
            className="btn"
            onClick={onCancel}
            data-testid="studio-delete-cancel"
          >
            Cancelar
          </button>
          <button
            type="button"
            className={
              scope === 'project' ? 'btn btn--danger' : 'btn btn--primary'
            }
            disabled={scope === 'project' && !canRemoveFromProject}
            onClick={() => onConfirm(scope)}
            data-testid="studio-delete-confirm"
          >
            {scope === 'project' ? 'Eliminar del proyecto' : 'Quitar del plano'}
          </button>
        </>
      }
    >
      <p className="studio-delete-dialog__lead">
        ¿Qué querés eliminar de <strong>{label}</strong>?
      </p>
      <div className="studio-delete-dialog__options" role="radiogroup" aria-label="Alcance de la eliminación">
        {hasPlacedSelection ? (
          <label className="studio-delete-dialog__option" data-testid="studio-delete-option-plan">
            <input
              type="radio"
              name="studio-delete-scope"
              checked={scope === 'plan'}
              onChange={() => setScope('plan')}
            />
            <span>
              <strong>Sólo del plano 3D</strong>
              <small>
                Los muebles quedan en la lista de muebles de la obra, sin colocar.
                Podés volver a colocarlos cuando quieras.
              </small>
            </span>
          </label>
        ) : null}
        <label
          className={
            canRemoveFromProject
              ? 'studio-delete-dialog__option'
              : 'studio-delete-dialog__option studio-delete-dialog__option--blocked'
          }
          data-testid="studio-delete-option-project"
        >
          <input
            type="radio"
            name="studio-delete-scope"
            checked={scope === 'project'}
            disabled={!canRemoveFromProject}
            onChange={() => setScope('project')}
          />
          <span>
            <strong>Del proyecto (lista de muebles)</strong>
            <small>
              {canRemoveFromProject
                ? 'Se quita la línea de la cotización con todas sus copias y se actualizan precio y BOM de la obra.'
                : 'La obra no permite quitar muebles de la cotización en este estado.'}
            </small>
          </span>
        </label>
      </div>
      {scope === 'project' && canRemoveFromProject ? (
        <ul className="studio-delete-dialog__targets" data-testid="studio-delete-targets">
          {targets.map((t) => (
            <li key={t.itemId}>
              <span>
                {t.code === '—' ? t.name : `${t.code} · ${t.name}`}
                {t.quantity > 1 ? ` (×${t.quantity})` : ''}
              </span>
              {t.otherSpacesPlacements > 0 ? (
                <small>
                  {' '}
                  también colocado en {t.otherSpacesPlacements}{' '}
                  ambiente{t.otherSpacesPlacements === 1 ? '' : 's'} más
                </small>
              ) : null}
            </li>
          ))}
        </ul>
