const submitPo = (): void => {
  const lines = draft.lines
    .filter((l) => l.materialId !== '' && l.quantity > 0)
    .map((l) => ({ kind: l.kind, materialId: l.materialId, quantity: l.quantity }));
  if (!draft.supplierId) {
    setError('Elegí un proveedor');
    return;
  }
  if (lines.length === 0) {
    setError('Agregá al menos una línea con material y cantidad');
    return;
  }
  void run(async () => {
    await onSavePurchaseOrder({
      id: poModal?.mode === 'edit' ? poModal.order?.id : undefined,
      supplierId: draft.supplierId,
      notes: draft.notes,
      items: lines,
    });
    setPoModal(null);
  });
};

// ─── Receive modal ───────────────────────────────────────────────────────

const [receiveQtys, setReceiveQtys] = useState<Record<string, number>>({});
const openReceive = (po: PurchaseOrder): void => {
  setReceiveModal(po);
  const qty: Record<string, number> = {};
  for (const it of po.items) {
    qty[`${it.kind}:${it.materialId}`] = Math.max(0, poRemaining(it));
  }
  setReceiveQtys(qty);
};

const submitReceive = (): void => {
  if (!receiveModal) return;
  for (const it of receiveModal.items) {
    const q = receiveQtys[`${it.kind}:${it.materialId}`] ?? 0;
    if (q < 0) {
      setError('Las cantidades no pueden ser negativas');
      return;
    }
    const rem = poRemaining(it);
    if (q > rem + 1e-6) {
      setError(`La cantidad a recibir de ${it.materialId} no puede superar lo pendiente (${formatQty(rem)})`);
      return;
    }
  }
  const lines = receiveModal.items
    .map((it) => ({
      kind: it.kind,
      materialId: it.materialId,
      quantity: receiveQtys[`${it.kind}:${it.materialId}`] ?? 0,
    }))
    .filter((l) => l.quantity > 0);
  if (lines.length === 0) {
    setError('Ingresá al menos una cantidad > 0');
    return;
  }
  void run(async () => {
    await onReceivePurchaseOrder(receiveModal.id, lines);
    setReceiveModal(null);
  });
};

export function SiteSurveyPanel({
  projectId,
  survey,
  handlers,
  canCapture = false,
  canVerify = false,
  canApprove = false,
  testId = 'site-survey-panel',
}: SiteSurveyPanelProps): ReactNode {
  const [newSpaceName, setNewSpaceName] = useState('');
  const [captureSpaceId, setCaptureSpaceId] = useState<string | null>(null);
  const [width, setWidth] = useState('');
  const [height, setHeight] = useState('');
  const [depth, setDepth] = useState('');
  const [captureNote, setCaptureNote] = useState('');
  const [error, setError] = useState<string | null>(null);

  const blockers = survey ? surveyFabricationBlockers(survey) : [];
  const surveyVerified = Boolean(survey?.verifiedAt);

  const startSurvey = (): void => {
    void handlers.onStart?.(projectId);
  };

  const addSpace = (): void => {
    const name = newSpaceName.trim();
    if (!name) {
      setError('El espacio necesita un nombre');
      return;
    }
    void handlers.onUpsertSpace?.(projectId, { name });
    setNewSpaceName('');
    setError(null);
  };

  const submitCapture = (spaceId: string): void => {
    const w = Number(width);
    const h = Number(height);
    if (!Number.isFinite(w) || w <= 0 || !Number.isFinite(h) || h <= 0) {
      setError('Ancho y alto (mm) deben ser mayores a cero');
      return;
    }
    const d = Number(depth);
    void handlers.onCaptureMeasures?.(projectId, spaceId, {
      widthMm: w,
      heightMm: h,
      ...(Number.isFinite(d) && d > 0 ? { depthMm: d } : {}),
      ...(captureNote.trim() ? { notes: captureNote.trim() } : {}),
    });
    setCaptureSpaceId(null);
    setWidth('');
    setHeight('');
    setDepth('');
    setCaptureNote('');
    setError(null);
  };

  if (!survey) {
    return (
      <div className="site-survey site-survey--empty" data-testid={testId}>
        <EmptyState
          icon={Ruler}
          title="Sin levantamiento estructurado"
          description="Cargá los espacios de la obra (cocina, closet…), levantá las medidas en sitio y aprobálas antes de liberar producción. Una medida preliminar nunca llega a CNC sin este gate."
          actionLabel={canCapture && handlers.onStart ? 'Iniciar levantamiento' : undefined}
          onAction={canCapture && handlers.onStart ? startSurvey : undefined}
        />
      </div>

